// 目録（JSON）を読み込み、ページ送り付きの一覧を作るサンプルです。
// 使い方: <div class="mikan-pager" data-src="目録のURL" data-per-page="20"></div>
document.querySelectorAll('.mikan-pager[data-src]').forEach(async (box) => {
  const perPage = Math.max(1, parseInt(box.dataset.perPage || '20', 10));
  let items = [];
  try {
    const response = await fetch(box.dataset.src);
    items = await response.json();
  } catch (error) {
    box.textContent = "一覧を読み込めませんでした。";
    return;
  }
  const pages = Math.max(1, Math.ceil(items.length / perPage));
  let page = 0;
  const list = document.createElement('ul');
  const nav = document.createElement('p');
  const prev = document.createElement('button');
  const next = document.createElement('button');
  const status = document.createElement('span');
  prev.type = next.type = 'button';
  prev.textContent = "← 前へ";
  next.textContent = "次へ →";
  nav.append(prev, ' ', status, ' ', next);
  box.append(list, nav);
  function show() {
    list.replaceChildren(...items.slice(page * perPage, (page + 1) * perPage).map((item) => {
      const li = document.createElement('li');
      const link = document.createElement('a');
      link.href = item.url;
      link.textContent = item.title;
      li.append(link, ' ', item.date || '');
      return li;
    }));
    status.textContent = (page + 1) + ' / ' + pages;
    prev.disabled = page === 0;
    next.disabled = page >= pages - 1;
  }
  prev.addEventListener('click', () => { page--; show(); });
  next.addEventListener('click', () => { page++; show(); });
  show();
});
